import {
	DevServerStatus,
	useBootDevServerMutation,
	useSubscribeToDevServerUpdatesSubscription
} from '@/generated/graphql'
import { useEffect, useState } from 'react'
import { chatEmitter, ChatEvents } from '../emitter'
import { APP_LAUNCH_DELAY } from '@/constants'
import { getDevServerProxyUrl } from './useDevServerUrl'
import { getDevServerId } from '../sandbox'
import { SandboxEnvironment } from '@/types'
import { router } from 'expo-router'

const pingHealthCheck = async ({ devServerUrl }: { devServerUrl: URL }) => {
	const url = new URL(devServerUrl)
	url.pathname = '/healthz'
	try {
		await fetch(url.toString())
	} catch (error) {
		console.error('Health check failed:', error)
	}
}

export function useBootServerAndLaunchAppAfterStreaming() {
	const [state, setState] = useState<{
		devServerId: string
		projectGroupId: string
	} | null>(null)
	const [bootDevServerMutation] = useBootDevServerMutation()
	const [isStreamingDone, setIsStreamingDone] = useState(false)
	const [devServerUrl, setDevServerUrl] = useState<URL | null>(null)

	useSubscribeToDevServerUpdatesSubscription({
		skip: !state,
		variables: {
			id: state?.devServerId!
		},
		onData: ({ data }) => {
			if (!data.data) return
			const session = data.data.devServerUpdate
			if (session.status === DevServerStatus.RUNNING) {
				setDevServerUrl(
					new URL(
						getDevServerProxyUrl({
							projectGroupId: state!.projectGroupId,
							projectGroupRevisionId: null,
							server: 'mobile',
							pathname: null
						})
					)
				)
			}
		}
	})

	function bootDevServerAndLaunchApp({
		projectGroupId
	}: {
		projectGroupId: string
	}) {
		setState({
			devServerId: getDevServerId({
				projectGroupId,
				projectGroupRevisionId: null,
				environment: SandboxEnvironment.BUILDER
			}),
			projectGroupId
		})
		bootDevServerMutation({ variables: { input: { projectGroupId } } }).then(
			async ({ data }) => {
				if (
					data?.bootDevServer.devServerSession.status ===
					DevServerStatus.RUNNING
				) {
					setDevServerUrl(
						new URL(
							getDevServerProxyUrl({
								projectGroupId,
								projectGroupRevisionId: null,
								server: 'mobile',
								pathname: null
							})
						)
					)
				}
			}
		)
	}

	useEffect(() => {
		let timeout: NodeJS.Timeout
		const handleStreamingDone = () => {
			timeout = setTimeout(() => {
				setIsStreamingDone(true)
			}, APP_LAUNCH_DELAY)
		}
		chatEmitter.on(ChatEvents.STREAMING_DONE, handleStreamingDone)

		return () => {
			chatEmitter.off(ChatEvents.STREAMING_DONE, handleStreamingDone)
			if (timeout) clearTimeout(timeout)
		}
	}, [])

	useEffect(() => {
		if (!devServerUrl) return
		if (!state) return
		if (!isStreamingDone) {
			const interval = setInterval(() => {
				pingHealthCheck({ devServerUrl })
			}, 3 * 60 * 1000)
			return () => {
				clearInterval(interval)
			}
		}
		router.push({
			pathname: '/launcher',
			params: {
				projectGroupId: state!.projectGroupId,
				metroServerHost: devServerUrl.host,
				isWeb: JSON.stringify(false)
			}
		})
		return
	}, [isStreamingDone, devServerUrl])

	return {
		bootDevServerAndLaunchApp
	}
}
